inlineScript.scriptBlock:
//on change of waiver - hide account and amount
this.disableOnWaiver = function (index) {
	var isWaived = this.context.binding.get("value").get(index).get("waiver");
	if (isWaived) {
		this.resetAccountAndAmount(index);
		this.disableAccount(index, false);
		this.disableAmount(index, false);
	} else {
		this.disableAccount(index, true);
		this.disableAmount(index, true);
	}
};

//On change of account class - reset data before choosing another account
this.resetAccountInfo = function (index) {
	this.resetAccountAndAmount(index);
	this.accountNumVis(index);
};

// on load of Product Code Data
this.getChargesOnLoad = function () {
	var productCode = this.context.options.productCode.get("value");
	if (!this.context.options.isChecker.get("value") && productCode != "" && productCode != null && !this.context.options.firstTimeCharges.get("value")) {
		this.context.options.isAmntChanged.set("value", false);
		this.ui.get("GetChargesBtn").click();
	}
};

this.getCharges = function () {
	var productCode = this.context.options.productCode.get("value");
	if (!this.context.options.isChecker.get("value") && productCode != "" && productCode != null) {
		this.context.options.isAmntChanged.set("value", false);
		this.ui.get("GetChargesBtn").click();
	}
};

this.calcDefaultAmnt = function () {
	if (this.context.options.hasFixedRate.get("value") && !!this.context.options.productCode.get("value")) {
		this.context.options.isAmntChanged.set("value", true);
		console.log("calcDefaultAmnt");
		this.ui.get("GetChargesBtn").click();
	}
};


//On Change Amount and Negotiated Exchange Rate - calculate Debited Amount
this.calculateDebitedAmount = function (index) {
	var chargeAmount = this.context.binding.get("value").get(index).get("changeAmount") || 0;
	var NegotiableRate = this.context.binding.get("value").get(index).get("debitedAmount").get("negotiatedExRate") || 0;
	var debitedAmount = chargeAmount * NegotiableRate;

	this.context.binding.get("value").get(index).get("debitedAmount").set("amountInAccount", debitedAmount);
};

//On Rate Type - Set Vis for Flat amount and fixed rate
this.rateTypeVis = function (value) {
	var index = value.ui.getIndex();
	var rateType = value.getData();
	var fixedRate = "Fixed Rate";
	var flatAmount = "Flat Amount";
	if (rateType != null && rateType == flatAmount) {
		this.fixedRateVis(false, index);

		this.ui.get("defaultPercentage[" + index + "]").setData(0);
		this.ui.get("changePercentage[" + index + "]").setData(0);
	} else if (rateType != null && rateType == fixedRate) {
		this.fixedRateVis(true, index);
	}
};

this.fixedRateVis = function (value, index) {
	var isChecker = this.context.options.isChecker.get("value");
	this.ui.get("defaultPercentage[" + index + "]").setVisible(value, true);
	this.ui.get("changePercentage[" + index + "]").setVisible(value, true);
	this.ui.get("changeAmount[" + index + "]").setEnabled(!value);
	if (isChecker && value) {
		this.ui.get("defaultPercentage[" + index + "]").setEnabled(false);
		this.ui.get("changePercentage[" + index + "]").setEnabled(false);
	}
	if (isChecker) {
		this.ui.get("changeAmount[" + index + "]").setEnabled(false);
	}

	this.ui.get("space1[" + index + "]").setVisible(false, !value);
};

//reusable
this.resetAccountAndAmount = function (index) {
	//Account
	this.ui.get("glAccountNo[" + index + "]").setData("");
	this.ui.get("customerAccountNo[" + index + "]").setData("");
	this.ui.get("accountBalance[" + index + "]").setData("");
	this.ui.get("accountBranchCode[" + index + "]").setData("");
	this.ui.get("balanceSign[" + index + "]").setData("");
	this.ui.get("accountCurrency[" + index + "]").setData("");
	this.ui.get("verifiedText[" + index + "]").setData("");
	//Amount
	this.ui.get("standardExchangeRate[" + index + "]").setData("");
	this.ui.get("debitedAmountInCurrency[" + index + "]").setData("");
	this.ui.get("negotiatedExchangeRate[" + index + "]").setData("");
};

//reusable
this.disableAccount = function (index, reset) {
	if (reset) {
		this.ui.get("debitAccounts[" + index + "]").setVisible(true, true);
		this.ui.get("Single_Select1[" + index + "]").setEnabled(true);
		this.accountNumVis(index);
		return;
	}
	//debitAccounts
	this.ui.get("debitAccounts[" + index + "]").setVisible(false, true);
	//   this.ui.get("Single_Select1[" + index + "]").setEnabled(false);
	//   this.ui.get("accountBranchCode[" + index + "]").setEnabled(false);
	//   this.ui.get("customerAccountNo[" + index + "]").setEnabled(false);
	//   this.ui.get("balanceSign[" + index + "]").setEnabled(false);
	//   this.ui.get("accountBalance[" + index + "]").setEnabled(false);
	//   this.ui.get("GLSection1[" + index + "]").setEnabled(false);
	//   this.ui.get("glAccountNo[" + index + "]").setEnabled(false);
	//   this.ui.get("verifyGLButton[" + index + "]").setEnabled(false);
	//   this.ui.get("accountCurrency[" + index + "]").setEnabled(false);
};

this.disableAmount = function (index, reset) {
	if (reset) {
		this.ui.get("debitAmounts[" + index + "]").setVisible(true, true);
		//	this.ui.get("negotiatedExchangeRate[" + index + "]").setEnabled(true);
		return;
	}
	//debitAmounts
	this.ui.get("debitAmounts[" + index + "]").setVisible(false, true);
	//   this.ui.get("standardExchangeRate[" + index + "]").setEnabled(false);
	//   this.ui.get("debitedAmountInCurrency[" + index + "]").setEnabled(false);
	//   this.ui.get("negotiatedExchangeRate[" + index + "]").setEnabled(false);
};

//====================================================================================================
//Generic Validate Positive amount (accepts 0) (Change Amount)
this.validatePositive = function (value) {
	if (value.getData() < 0) {
		value.setValid(false, "Must be >= 0");
		//		value.setData(0.0);
	} else {
		value.setValid(true);
	}
};

//Generic Validate Digits Only (Account Branch Code)
this.validateDigits = function (value) {
	var index = value.ui.getIndex();
	if (isNaN(Number(value.getData()))) {
		value.setData("");
		value.setValid(false, "must be digits");
		return false;
	} else {
		value.setValid(true);
		return true;
	}
};

//On Change of Change Percentage - Validate Change percentage before calculate change amount
this.amountValidation = function (value) {
	var index = value.ui.getIndex();
	if (this.context.binding.get("value").get(index).get("rateType") == "Fixed Rate") {
		if (value.getData() < 0 || value.getData() > 100) {
			value.setData(0);
			value.setValid(false, "Must be >= 0 and < 100");
		} else {
			value.setValid(true);
			this.calcChangeAmnt(value);
		}
	}
};

var newIndex;
//call from amountValidation function - Calculate change amount service call
this.calcChangeAmnt = function (value) {
	var index = value.ui.getIndex();

	var requestAmnt = this.context.options.amountCollectableByNBE.get("value");
	var changePercentage = this.context.binding.get("value").get(index).get("changePercentage");

	var concatedDefault = requestAmnt + "," + changePercentage;
	this.ui.get("calculateChangeAmount1[" + index + "]").execute(concatedDefault);
	newIndex = index;
};

//On result of calculateChangeAmount1 - Map Service call ouput
this.setChangeAmnt = function () {
	var index = newIndex;
	var changeAmount = this.context.options.calculatedChangeAmnt.get("value");
	if (!!changeAmount) {
		this.context.binding.get("value").get(index).set("changeAmount", changeAmount);
	} else {
		this.context.binding.get("value").get(index).set("changeAmount", 0);
	}
};

//On change of Account Num - Set Account Info for each customer Account
this.fillAccountData = function (value) {
	var index = value.ui.getIndex();

	for (var i = 0; i < this.context.options.chargesCustomerAccountList.get("value").length(); i++) {
		if (this.context.options.chargesCustomerAccountList.get("value").get(i).get("accountNO") == value.getData()) {
			//Set isOverDraft
			var commClassCode = this.context.options.chargesCustomerAccountList.get("value").get(i).get("accountClassCode");
			var code = commClassCode.substring(0, 1);

			if (code == "O" || code == "D") {
				this.context.binding.get("value").get(index).get("debitedAccount").set("isOverDraft", true);
			} else {
				this.context.binding.get("value").get(index).get("debitedAccount").set("isOverDraft", false);
			}

			//Set Account Info
			this.context.binding.get("value").get(index).get("debitedAccount").set("branchCode", this.context.options.chargesCustomerAccountList.get("value").get(i).get("branchCode"));
			this.context.binding.get("value").get(index).get("debitedAccount").set("currency", {});
			this.ui.get("accountCurrency[" + index + "]").setData(this.context.options.chargesCustomerAccountList.get("value").get(i).get("currencyCode"));
			//			this.context.binding.get("value").get(index).get("debitedAccount").get("currency").set("vale", this.context.options.chargesCustomerAccountList.get("value").get(i).get("currencyCode"));
			//			this.context.binding.get("value").get(index).get("debitedAccount").set("currency",this.context.options.chargesCustomerAccountList.get("value").get(i).get("currencyCode"));
			this.context.binding.get("value").get(index).get("debitedAccount").set("balance", this.context.options.chargesCustomerAccountList.get("value").get(i).get("balance"));
			this.context.binding.get("value").get(index).get("debitedAccount").set("balanceSign", this.context.options.chargesCustomerAccountList.get("value").get(i).get("balanceType"));

			this.context.options.index.set("value", index);
		}
	}
};

//On change of GL Account Num - Reset Data on GL account change
this.resetGLButton = function (value) {
	var index = value.ui.getIndex();
	this.context.binding.get("value").get(index).set("isGLFound", false);
	this.context.binding.get("value").get(index).set("glVerifyMSG", "");
};

//On click of validate GL Btn - Call A service call to validate GL
this.executeGL = function (value) {
	var index = value.ui.getIndex();
	//	value.setEnabled(false);

	var data = this.context.binding.get("value").get(index).get("debitedAccount").get("glAccountNo");
	this.ui.get("CheckexistingGLAccount1[" + index + "]").execute(data);
};

//On result of Validate GL - Map the result of GL service call
this.validGlAccount = function (value) {
	record = value.ui.getIndex();
	if (!this.context.binding.get("value").get(record).get("isGLFound")) {
		this.ui.get("glAccountNo[" + record + "]").setValid(false, "Account Not Found!");
		this.context.binding.get("value").get(record).set("glVerifyMSG", "");
	} else {
		this.ui.get("glAccountNo[" + record + "]").setValid(true);
		this.context.binding.get("value").get(record).set("glVerifyMSG", "Verified");
	}
};

//On change of Account Cry - Apply vis and Call A service to get exchange rate between Default Cry and Account Cry
this.setExchangeRate = function (value) {
	var index = value.ui.getIndex();
	var cryCode = value.getData();
	//	var cryCode = this.context.binding.get("value").get(index).get("debitedAccount").get("currency").get("value");
	if (cryCode != "" && cryCode != null && cryCode != undefined) {
		if (this.ui.get("defaultCurrency[" + index + "]").getData() == cryCode) {
			this.ui.get("standardExchangeRate[" + index + "]").setData(1.0);
			this.ui.get("negotiatedExchangeRate[" + index + "]").setData(1.0);
			this.ui.get("negotiatedExchangeRate[" + index + "]").setEnabled(false);
		} else {
			//			this.ui.get("NegotiatedExchangeRate["+index+"]").setEnabled(false);
			var defaultCurrency = this.ui.get("defaultCurrency[" + index + "]").getData();
			var accountCurrency = cryCode;

			concatedCurrency = { ccFrom: defaultCurrency, ccTo: accountCurrency, type: "TRANSFER", sType: "S" };
			var inputCurr = JSON.stringify(concatedCurrency);
			this.ui.get("GetExchangeRate[" + index + "]").execute(inputCurr);
		}
	}
};

//On Result of get exchange rate
this.setExServiceResults = function (value) {
	var index = value.ui.getIndex();

	var rate = this.context.options.exRate.get("value");
	this.ui.get("standardExchangeRate[" + index + "]").setData(Number(rate.toFixed(6)));
	this.ui.get("negotiatedExchangeRate[" + index + "]").setData(Number(rate.toFixed(6)));
	this.ui.get("negotiatedExchangeRate[" + index + "]").setEnabled(true);
};

//On Debited Amount in Account Currency and Account Balance- validate is over Draft
this.validateOverDraft = function (value) {
	var index = value.ui.getIndex();
	var accountClass = this.context.binding.get("value").get(index).get("debitedAccount").get("accountClass").get("name");
	if (accountClass !== "001") {
		this.ui.get("debitedAmountInCurrency[" + index + "]").setValid(true);
		return;
	}
	var accountBalance = this.ui.get("accountBalance[" + index + "]").getData();
	var debitedAmount = this.ui.get("debitedAmountInCurrency[" + index + "]").getData();
	if (debitedAmount > accountBalance) {
		if (this.context.binding.get("value").get(index).get("debitedAccount").get("isOverDraft") == true) {
			this.ui.get("debitedAmountInCurrency[" + index + "]").setValid(false, "WARNING: Must be < Account Balance");
		} else if (this.context.binding.get("value").get(index).get("debitedAccount").get("isOverDraft") == false) {
			this.ui.get("debitedAmountInCurrency[" + index + "]").setValid(false, "Error: Must be < Account Balance");
		}
	} else {
		this.ui.get("debitedAmountInCurrency[" + index + "]").setValid(true);
	}
};

//++++++++++++++++++++++++++++++++++++++++++++++Error Handling+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
this.AjaxErrorHandling = function (errorMSG) {
	this.context.options.alertMessage.set("value", errorMSG);
	this.context.options.errorVis.set("value", "EDITABLE");
};
//========================================================================================================================================
// Reusable function to set visibility and enabled state
this.setUIVisibilityAndState = function (ui, index, config) {
	for (var i = 0; i < config.length; i++) {
		var item = config[i];
		ui.get(item.name + "[" + index + "]").setVisible(item.visible, true);
		if (item.enabled !== undefined) {
			ui.get(item.name + "[" + index + "]").setEnabled(item.enabled);
		}
		if (item.data !== undefined) {
			ui.get(item.name + "[" + index + "]").setData(item.data);
		}
	}
};

// Handle Customer Account
this.handleCustomerAccount = function (index, isChecker) {
	var config = [
		{ name: "balanceSign", visible: true },
		{ name: "accountBalance", visible: true },
		{ name: "customerAccountNo", visible: true, enabled: !isChecker },
		{ name: "verifyGLButton", visible: false },
		{ name: "glAccountNo", visible: false },
		{ name: "GLSection1", visible: false },
		{ name: "accountCurrency", visible: true, enabled: false },
		{ name: "accountBranchCode", visible: true, enabled: false },
	];

	// if (!isChecker) {
	// 	config.push({ name: "glAccountNo", data: "" });
	// } else {
	// 	config.push({ name: "customerAccountNo", enabled: false });
	// }

	this.setUIVisibilityAndState(this.ui, index, config);
	this.ui.get("accountBranchCode[" + index + "]").setEnabled(false);
};

// Handle GL Account
this.handleGLAccount = function (index, isChecker) {
	var config = [
		{ name: "balanceSign", visible: false },
		{ name: "accountBalance", visible: false },
		{ name: "customerAccountNo", visible: false },
		{ name: "glAccountNo", visible: true, enabled: !isChecker },
		{ name: "GLSection1", visible: true, enabled: !isChecker },
		{ name: "verifyGLButton", visible: !isChecker, enabled: !isChecker },
		{ name: "accountCurrency", visible: true, enabled: !isChecker },
		{ name: "accountBranchCode", visible: true, enabled: !isChecker },
	];

	// if (!isChecker) {
	// 	config.push({ name: "customerAccountNo", data: null });
	// 	this.context.binding.get("value").get(index).get("debitedAccount").set("isOverDraft", null);
	// }

	this.setUIVisibilityAndState(this.ui, index, config);
};

// Main function
this.accountNumVis = function (value) {
	var index = value;
	var accountClass = this.context.binding.get("value").get(index).get("debitedAccount").get("accountClass").get("name");
	var isChecker = this.context.options.isChecker.get("value");

	if (isChecker) {
		this.ui.get("Single_Select1[" + index + "]").setEnabled(false);
	}
	if (accountClass === "001") {
		// Customer
		this.handleCustomerAccount(index, isChecker);
	} else {
		// GL
		this.handleGLAccount(index, isChecker);
	}
};
